import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { sql } from "drizzle-orm";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const HANDOVER_STATUSES = [
  "pending",
  "accepted",
  "declined",
  "canceled",
  "expired",
] as const;

/**
 * One row per offer of recorded ownership. At most one `pending` row per
 * workspace — a lapsed offer is moved off `pending` before a new one is
 * inserted, and the partial unique index is the backstop.
 */
export const ownershipHandovers = sqliteTable(
  "ownership_handovers",
  {
    id: idColumn(),
    ...tenantColumns,
    fromUserId: text("from_user_id").notNull(),
    toUserId: text("to_user_id").notNull(),
    status: text("status", { enum: HANDOVER_STATUSES }).notNull(),
    expiresAt: text("expires_at").notNull(),
    resolvedAt: text("resolved_at"),
    ...timestampColumns,
  },
