/**
 * Persistence for recorded-ownership offers. At most one pending row per org.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, eq, gt, lte, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOwnershipHandover } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { OwnershipHandover, OwnershipHandoverStatus } from "@/types/organization";

export interface NewOwnershipOffer {
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly createdAt: IsoTimestamp;
  readonly expiresAt: IsoTimestamp;
}

/**
 * Expires any lapsed pending offer, then inserts a new one. Returns null when
 * a still-open offer already occupies the workspace.
 */
export async function createOffer(
  input: NewOwnershipOffer,
): Promise<OwnershipHandover | null> {
  const db = getDb();

  db.update(ownershipHandovers)
    .set({
      status: "expired",
      resolvedAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, input.orgId),
        eq(ownershipHandovers.status, "pending"),
        lte(ownershipHandovers.expiresAt, input.createdAt),
      ),
    )
    .run();

  const open = db
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, input.orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  if (open) return null;

  try {
    const row = db
      .insert(ownershipHandovers)
      .values({
        id: newId(),
        orgId: input.orgId,
        fromUserId: input.fromUserId,
        toUserId: input.toUserId,
        status: "pending",
        expiresAt: input.expiresAt,
        resolvedAt: null,
        createdAt: input.createdAt,
        updatedAt: input.createdAt,
      })
      .returning()
      .get();
    return toOwnershipHandover(row);
  } catch (error) {
    if (isUniqueViolation(error)) return null;
    throw error;
  }
}

/** The workspace's pending offer, lapsed or not. Callers decide which. */
export async function findPending(orgId: OrgId): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: Exclude<OwnershipHandoverStatus, "pending" | "expired">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt, updatedAt: resolvedAt })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, id),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${id} was not found`);
  return toOwnershipHandover(row);
}

/**
 * Withdraws a still-open offer when one of its participants leaves. A lapsed
 * offer is left alone: it is already not open.
 */
export async function cancelOpenForUser(orgId: OrgId, userId: UserId): Promise<void> {
  const now = toIsoTimestamp(new Date());
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: now, updatedAt: now })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, now),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}

function isUniqueViolation(error: unknown): boolean {
  const seen = new Set<unknown>();
  let current: unknown = error;
  while (current && typeof current === "object" && !seen.has(current)) {
    seen.add(current);
    const code = (current as { code?: unknown }).code;
    if (code === "SQLITE_CONSTRAINT_UNIQUE" || code === "SQLITE_CONSTRAINT") {
      return true;
    }
    if (
      current instanceof Error &&
      /UNIQUE constraint failed/i.test(current.message)
    ) {
      return true;
    }
    current = (current as { cause?: unknown }).cause;
  }
  return false;
}

