import { afterAll, describe, expect, it, vi } from "vitest";
import { OwnershipHandoverError, isDomainError, toAppError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { subscribe } from "@/lib/event-bus";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import { listActivity } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { UserId } from "@/types/common";

let cleanup: () => void;
let detach: Unsubscribe;

afterAll(() => {
  detach?.();
  cleanup?.();
});

describe("ownership handover", () => {
  it("transfers ownership and refuses the cases in the contract", async () => {
    cleanup = await useTemporaryDatabase();
    detach = registerActivityListeners();

    const tenant = await createTenant("handover", "growth");
    const orgId = tenant.org.id;
    const owner = tenant.actors.owner;
    const viewer = tenant.actors.viewer;
    const admin = tenant.actors.admin;
    const member = tenant.actors.member;

    await expect(
      orgService.initiateOwnershipHandover(viewer, orgId, admin.userId),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await memberRepo.updateMemberRole(
      orgId,
      (await memberRepo.findMember(orgId, admin.userId))!.id,
      "owner",
    );
    const coOwner = { ...admin, role: "owner" as const };
    await expect(
      orgService.initiateOwnershipHandover(coOwner, orgId, viewer.userId),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, owner.userId),
    ).rejects.toMatchObject({ reason: "self" });

    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, "usr_missing" as UserId),
    ).rejects.toBeInstanceOf(NotFoundError);

    const other = await createTenant("handover-other", "growth");
    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      orgService.initiateOwnershipHandover(owner, other.org.id, viewer.userId),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const removed = await memberRepo.findMember(orgId, member.userId);
    await memberService.removeMember(owner, { orgId, memberId: removed!.id });
    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, member.userId),
    ).rejects.toBeInstanceOf(NotFoundError);

    const offer = await orgService.initiateOwnershipHandover(
      owner,
      orgId,
      viewer.userId,
    );
    expect(offer.status).toBe("pending");
    expect(offer.resolvedAt).toBeNull();
    expect(offer.fromUserId).toBe(owner.userId);
    expect(offer.toUserId).toBe(viewer.userId);
    expect(new Date(offer.expiresAt).getTime() - new Date(offer.createdAt).getTime()).toBe(
      7 * 24 * 60 * 60 * 1000,
    );

    const visible = await orgService.getPendingOwnershipHandover(admin, orgId);
    expect(visible?.toUserId).toBe(viewer.userId);
    await expect(
      orgService.getPendingOwnershipHandover(owner, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const notes = await notificationRepo.listNotifications({
      orgId,
      recipientId: viewer.userId,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(notes.items.map((row) => row.kind)).toContain("ownership_handover");
    const ownerNotes = await notificationRepo.listNotifications({
      orgId,
      recipientId: owner.userId,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(ownerNotes.items.some((row) => row.kind === "ownership_handover")).toBe(false);

    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, admin.userId),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    await expect(orgService.acceptOwnershipHandover(admin, orgId)).rejects.toMatchObject({
      reason: "nothing_pending",
    });
    await expect(orgService.declineOwnershipHandover(owner, orgId)).rejects.toMatchObject({
      reason: "nothing_pending",
    });

    const selfError = new OwnershipHandoverError("self");
    expect(isDomainError(selfError)).toBe(true);
    expect(toAppError(selfError).code).toBe("conflict");

    const events: unknown[] = [];
    const off = subscribe("member.role_changed", (payload) => {
      events.push(payload);
    });
    const transferred = new Promise((resolve) => {
      const stop = subscribe("organization.ownership_transferred", (payload) => {
        stop();
        resolve(payload);
      });
    });

    const next = await orgService.acceptOwnershipHandover(viewer, orgId);
    off();
    expect(next.ownerId).toBe(viewer.userId);
    expect(events).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          actorId: viewer.userId,
          from: "viewer",
          to: "owner",
        }),
        expect.objectContaining({
          actorId: viewer.userId,
          from: "owner",
          to: "admin",
        }),
      ]),
    );
    await expect(transferred).resolves.toMatchObject({
      actorId: viewer.userId,
      fromUserId: owner.userId,
      toUserId: viewer.userId,
    });

    const audit = await listActivity(viewer, {
      orgId,
      action: ["organization.ownership_transferred"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      actorId: viewer.userId,
      subjectKind: "organization",
      subjectId: orgId,
      metadata: { fromUserId: owner.userId, toUserId: viewer.userId },
    });

    const previous = await memberRepo.findMember(orgId, owner.userId);
    expect(previous?.role).toBe("admin");
    const nowOwner = await memberRepo.findMember(orgId, viewer.userId);
    expect(nowOwner?.role).toBe("owner");

    await expect(
      billingService.changePlan(owner, {
        orgId,
        plan: "enterprise",
        interval: "monthly",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const staleViewer = viewer;
    const changed = await billingService.changePlan(staleViewer, {
      orgId,
      plan: "enterprise",
      interval: "monthly",
    });
    expect(changed.plan).toBe("enterprise");

    await expect(orgService.acceptOwnershipHandover(viewer, orgId)).rejects.toMatchObject({
      reason: "nothing_pending",
    });
    expect(await orgService.getPendingOwnershipHandover(viewer, orgId)).toBeNull();

    await memberService.removeMember(
      { ...viewer, role: "owner" },
      { orgId, memberId: previous!.id },
    );

    const again = await orgService.initiateOwnershipHandover(
      { ...viewer, role: "owner" },
      orgId,
      admin.userId,
    );
    const declined = await orgService.declineOwnershipHandover(admin, orgId);
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).not.toBeNull();
    expect(await orgService.getPendingOwnershipHandover(admin, orgId)).toBeNull();

    const third = await orgService.initiateOwnershipHandover(
      { ...viewer, role: "owner" },
      orgId,
      coOwner.userId,
    );
    const withdrawn = await orgService.cancelOwnershipHandover(
      { ...viewer, role: "owner" },
      orgId,
    );
    expect(withdrawn.status).toBe("canceled");
    expect(withdrawn.id).toBe(third.id);
    await expect(
      orgService.cancelOwnershipHandover({ ...viewer, role: "owner" }, orgId),
    ).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(orgService.declineOwnershipHandover(coOwner, orgId)).rejects.toMatchObject({
      reason: "nothing_pending",
    });

    const open = await orgService.initiateOwnershipHandover(
      { ...viewer, role: "owner" },
      orgId,
      coOwner.userId,
    );
    const targetMember = await memberRepo.findMember(orgId, coOwner.userId);
    await memberService.removeMember(
      { ...viewer, role: "owner" },
      { orgId, memberId: targetMember!.id },
    );
    expect(await orgService.getPendingOwnershipHandover(viewer, orgId)).toBeNull();
    void again;
    void open;

    vi.useFakeTimers();
    try {
      const fresh = await createTenant("handover-clock", "growth");
      vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));
      const timed = await orgService.initiateOwnershipHandover(
        fresh.actors.owner,
        fresh.org.id,
        fresh.userIds.member,
      );
      vi.setSystemTime(new Date(new Date(timed.expiresAt).getTime() - 1));
      expect(
        await orgService.getPendingOwnershipHandover(fresh.actors.member, fresh.org.id),
      ).not.toBeNull();

      vi.setSystemTime(new Date(timed.expiresAt));
      expect(
        await orgService.getPendingOwnershipHandover(fresh.actors.member, fresh.org.id),
      ).toBeNull();
      await expect(
        orgService.acceptOwnershipHandover(fresh.actors.member, fresh.org.id),
      ).rejects.toMatchObject({ reason: "expired" });
      await expect(
        orgService.declineOwnershipHandover(fresh.actors.member, fresh.org.id),
      ).rejects.toMatchObject({ reason: "expired" });
      await expect(
        orgService.cancelOwnershipHandover(fresh.actors.owner, fresh.org.id),
      ).rejects.toMatchObject({ reason: "nothing_pending" });
      const replacement = await orgService.initiateOwnershipHandover(
        fresh.actors.owner,
        fresh.org.id,
        fresh.userIds.admin,
      );
      expect(replacement.status).toBe("pending");
      expect(replacement.toUserId).toBe(fresh.userIds.admin);

      const already = await memberRepo.findMember(fresh.org.id, fresh.userIds.admin);
      await memberRepo.updateMemberRole(fresh.org.id, already!.id, "owner");
      const accepted = await orgService.acceptOwnershipHandover(
        { ...fresh.actors.admin, role: "owner" },
        fresh.org.id,
      );
      expect(accepted.ownerId).toBe(fresh.userIds.admin);
      const stepped = await memberRepo.findMember(fresh.org.id, fresh.userIds.owner);
      expect(stepped?.role).toBe("admin");
      const kept = await memberRepo.findMember(fresh.org.id, fresh.userIds.admin);
      expect(kept?.role).toBe("owner");
    } finally {
      vi.useRealTimers();
    }
  });
});

