  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await requireOrg(orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const expiresAt = toIsoTimestamp(new Date(now.getTime() + HANDOVER_WINDOW_MS));

  const created = await handoverRepo.createOffer({
    orgId,
    fromUserId: actor.userId,
    toUserId,
    createdAt,
    expiresAt,
  });
  if (!created) throw new OwnershipHandoverError("pending_exists");

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered ownership of this workspace",
    body: `${actor.userId} offered you ownership of this workspace`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return created;
}

/**
 * The offered member becomes the recorded owner and holds the owner role.
 * The previous owner steps down to admin when they still hold that role.
 * Promotion happens first so the workspace never lacks an owner.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = await requireOffereeOffer(actor, orgId);
  const org = await requireOrg(orgId);

  const accepter = await memberRepo.findMember(orgId, actor.userId);
  if (!accepter || accepter.status !== "active") {
    throw new NotFoundError("Member", actor.userId);
  }

  const roleChanges: { memberId: MemberId; from: Role; to: Role }[] = [];

  if (accepter.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, accepter.id, "owner");
    roleChanges.push({
      memberId: updated.id,
      from: accepter.role,
      to: updated.role,
    });
  }

  if (org.ownerId !== actor.userId) {
    const previous = await memberRepo.findMember(orgId, org.ownerId);
    if (previous && previous.status === "active" && previous.role === "owner") {
      const updated = await memberRepo.updateMemberRole(orgId, previous.id, "admin");
      roleChanges.push({
        memberId: updated.id,
        from: previous.role,
        to: updated.role,
      });
    }
  }

  const updatedOrg = await orgRepo.updateOrgOwner(orgId, actor.userId);
  await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  for (const change of roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: org.ownerId,
    toUserId: actor.userId,
  });

  return updatedOrg;
}

/** The offered member declines. Nothing stays pending. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = await requireOffereeOffer(actor, orgId);
  return handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await requireOrg(orgId);
  assertRecordedOwner(actor, org);

  const pending = await handoverRepo.findPending(orgId);
  if (!pending || isLapsed(pending.expiresAt, new Date())) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    pending.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

/** The open offer, or null. A lapsed offer is not shown and does not count. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const pending = await handoverRepo.findPending(orgId);
  if (!pending || isLapsed(pending.expiresAt, new Date())) return null;
  return pending;
}

async function requireOrg(orgId: OrgId): Promise<Organization> {
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/** Recorded owner only. A second member who merely holds the owner role is refused. */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.userId === org.ownerId) return;

  const decision = explain(actor, "org:delete", orgResource(org.id));
  throw new PermissionDeniedError("org:delete", {
    allowed: false,
    action: "org:delete",
    resourceKind: "organization",
    reason: decision.allowed ? "denied_by_role" : decision.reason,
  });
}

/**
 * Accept and decline are only the offered member's. A lapsed offer refuses
 * with `expired` and is left unchanged; anyone else, or no open offer, is
 * `nothing_pending`.
 */
async function requireOffereeOffer(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPending(orgId);
  if (!pending) throw new OwnershipHandoverError("nothing_pending");
  if (isLapsed(pending.expiresAt, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  if (pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return pending;
}

/** Open through the instant before `expiresAt`; closed from that instant on. */
function isLapsed(expiresAt: IsoTimestamp, now: Date): boolean {
  return new Date(expiresAt).getTime() <= now.getTime();
}
